    def entityParser(self, text: str) -> str:
        reps = [('&quot;', '"'), ('&apos;', "'"), ('&amp;', '&'),
                ('&gt;', '>'), ('&lt;', '<'), ('&frasl;', '/')]
        reps.sort(key=lambda p: -len(p[0]))
        for e, c in reps:
            text = text.replace(e, c)
