class Solution {
public:
    string entityParser(string text) {
        vector<pair<string,string>> reps = {{"&quot;","\""},{"&apos;","'"},{"&amp;","&"},{"&gt;",">"},{"&lt;","<"},{"&frasl;","/"}};
        sort(reps.begin(), reps.end(), [](auto&a, auto&b){return a.first.size()>b.first.size();});
        for (auto& [e,c] : reps) {
            size_t pos = 0;
            while ((pos = text.find(e, pos)) != string::npos) {
                text.replace(pos, e.size(), c);
                pos += c.size();
            }
        }
        return text;
    }
};

