class Solution {
    public String entityParser(String text) {
        String[][] reps = {{"&quot;","\""},{"&apos;","'"},{"&amp;","&"},{"&gt;",">"},{"&lt;","<"},{"&frasl;","/"}};
        java.util.Arrays.sort(reps, (a,b)->b[0].length()-a[0].length());
        StringBuilder sb = new StringBuilder(text);
        for (String[] r : reps) {
            int idx;
            while ((idx = sb.indexOf(r[0])) != -1) {
                sb.replace(idx, idx + r[0].length(), r[1]);
            }
        }
        return sb.toString();
    }
}

