class Solution:
    def entityParser(self, text: str) -> str:
        mp = {'&quot;': '"', '&apos;': "'", '&amp;': '&',
              '&gt;': '>', '&lt;': '<', '&frasl;': '/'}
        res = []
        i, n = 0, len(text)
        while i < n:
            if text[i] == '&':
                matched = False
                for l in range(7, 3, -1):
                    if text[i:i+l] in mp:
                        res.append(mp[text[i:i+l]])
                        i += l
                        matched = True
                        break
                if not matched:
                    res.append('&')
                    i += 1
            else:
                res.append(text[i])
                i += 1
        return ''.join(res)

