class Solution {
public:
    string entityParser(string text) {
        unordered_map<string,char> mp = {{"&quot;",'"'},{"&apos;",'\''},{"&amp;",'&'},{"&gt;">,'>'},{"&lt;",'<'},{"&frasl;",'/'}};
        string res;
        int i = 0, n = text.size();
        while (i < n) {
            if (text[i] == '&') {
                bool matched = false;
                for (int l = 7; l >= 4 && !matched; --l) {
                    if (i + l <= n && mp.count(text.substr(i, l))) {
                        res += mp[text.substr(i, l)];
                        i += l;
                        matched = true;
                    }
                }
                if (!matched) { res += '&'; ++i; }
            } else {
                res += text[i++];
            }
        }
        return res;
    }
};

