class Solution {
    public String entityParser(String text) {
        java.util.Map<String,Character> mp = new java.util.HashMap<>();
        mp.put("&quot;", '"'); mp.put("&apos;", '\''); mp.put("&amp;", '&');
        mp.put("&gt;", '>'); mp.put("&lt;", '<'); mp.put("&frasl;", '/');
        StringBuilder sb = new StringBuilder();
        int i = 0, n = text.length();
        while (i < n) {
            if (text.charAt(i) == '&') {
                boolean matched = false;
                for (int l = 7; l >= 4 && !matched; --l) {
                    if (i + l <= n) {
                        Character c = mp.get(text.substring(i, i + l));
                        if (c != null) { sb.append(c); i += l; matched = true; }
                    }
                }
                if (!matched) { sb.append('&'); ++i; }
            } else {
                sb.append(text.charAt(i++));
            }
        }
        return sb.toString();
    }
}

